} else if (pick == 1) {
    // Linker: pick an executable kind from enum range
    EShExecutable exe = (EShExecutable)(*FUZZ_PARAM(unsigned int) % 2u);
    raw = ShConstructLinker(exe, 0 /*debugOptions unused*/);
    if (!raw) { FUZZ_BAIL(); }
    p = new ShHandle(raw);
    FUZZ_SET_ATTR_STR(p, "kind", "linker");
    FUZZ_SET_ATTR_PTR(p, "raw", (void*)raw);
} else {
    // Uniform map: no parameters
    raw = ShConstructUniformMap();
    if (!raw) { FUZZ_BAIL(); }
    p = new ShHandle(raw);
    FUZZ_SET_ATTR_STR(p, "kind", "uniform_map");
    FUZZ_SET_ATTR_PTR(p, "raw", (void*)raw);
}

// Define the required output variable and ensure it is non-null
ShHandle* handle = p;
FUZZ_ASSERT(handle != nullptr, "constructed ShHandle* is null");
// Validation: Sh* initialized; constructed via correct API; wrapped in heap object; tagged with kind/raw for downstream; non-null output.

