import random
from typing import List

# We generate valid GLSL/ESSL/HLSL shader texts, suitable for use in:
# - ShCompile (legacy C API): accepts 1..3 strings that are concatenated
# - glslang::TShader::setStrings*(...)
# - glslang_shader_set_preprocessed_code
# - glslang_program_add_source_text (stage is chosen by fuzzer)
#
# Strategy:
# - Produce short, self-contained shader snippets for multiple stages
# - Include variants for GLSL desktop (#version 450 core), ESSL (#version 310 es), and HLSL (no #version)
# - Ensure code compiles standalone (has an entry point) and uses basic features exercised by glslang
# - Compose 1..3 chunks that can be concatenated safely. First chunk contains #version (for GLSL/ESSL)
# - Limit size to <= 4096 bytes
#
# The fuzzer may pass explicit lengths or rely on NUL-termination, so we return bytes with a trailing NUL

GLSL_VERTEX_450 = """
#version 450 core
layout(location=0) in vec3 aPos;
layout(location=1) in vec2 aUV;
layout(location=0) out vec2 vUV;
layout(std140, binding = 0) uniform UBO { mat4 uMVP; };
void main() {
    vUV = aUV;
    gl_Position = uMVP * vec4(aPos, 1.0);
}
""".strip() + "\n"

GLSL_FRAGMENT_450 = """
#version 450 core
layout(location=0) in vec2 vUV;
layout(location=0) out vec4 FragColor;
uniform sampler2D tex0;
void main() {
    vec4 c = texture(tex0, vUV);
    FragColor = vec4(c.rgb, 1.0);
}
""".strip() + "\n"

GLSL_COMPUTE_450 = """
#version 450 core
layout(local_size_x = 8, local_size_y = 8, local_size_z = 1) in;
layout(binding = 0, rgba8) uniform writeonly image2D dstImg;
void main() {
    ivec2 p = ivec2(gl_GlobalInvocationID.xy);
    vec4 v = vec4(fract(sin(float(p.x))*43758.5), fract(sin(float(p.y))*12345.6), 0.0, 1.0);
    imageStore(dstImg, p, v);
}
""".strip() + "\n"

ESSL_VERTEX_310 = """
#version 310 es
precision highp float;
layout(location=0) in vec2 aPos;
layout(location=1) in vec2 aUV;
layout(location=0) out vec2 vUV;
uniform mat3 uM;
void main() {
    vUV = aUV;
    vec3 p = uM * vec3(aPos, 1.0);
    gl_Position = vec4(p.xy, 0.0, 1.0);
}
""".strip() + "\n"

ESSL_FRAGMENT_310 = """
#version 310 es
precision mediump float;
layout(location=0) in vec2 vUV;
layout(location=0) out vec4 oColor;
uniform sampler2D tex0;
void main() {
    oColor = texture(tex0, vUV);
}
""".strip() + "\n"

# Minimal valid HLSL vertex/fragment pairs for glslang when EShMsgReadHlsl is used
HLSL_VS = """
float4x4 uMVP : register(b0);
struct VSIn { float3 pos : POSITION; float2 uv : TEXCOORD0; };
struct VSOut { float4 pos : SV_Position; float2 uv : TEXCOORD0; };
VSOut main(VSIn i) {
    VSOut o;
    o.pos = mul(uMVP, float4(i.pos, 1.0));
    o.uv = i.uv;
    return o;
}
""".strip() + "\n"

HLSL_PS = """
Texture2D tex0 : register(t0);
SamplerState samp0 : register(s0);
struct PSIn { float4 pos : SV_Position; float2 uv : TEXCOORD0; };
float4 main(PSIn i) : SV_Target {
    return tex0.Sample(samp0, i.uv);
}
""".strip() + "\n"

# Extra small utility chunks that are safe to concatenate after a #version-bearing header
GLSL_PREAMBLE_SNIPPETS = [
    """
#define F(x) ((x) * (x))
""".strip() + "\n",
    """
const float kPi = 3.14159265;
""".strip() + "\n",
    """
// noop preamble chunk
""".strip() + "\n",
]

# Small function snippets that can be appended and used optionally
GLSL_FUNC_SNIPPETS = [
    """
float noise1(float x) {
    return fract(sin(x) * 43758.5453);
}
""".strip() + "\n",
    """
vec3 tonemap(vec3 c) {
    return c / (c + vec3(1.0));
}
""".strip() + "\n",
]

# Compose 1..3 chunks into a single shader source that remains valid when concatenated

def make_glsl_pipeline(rng: random.Random) -> List[str]:
    # Choose a pipeline kind: 0 = vert, 1 = frag, 2 = compute, 3 = vert+frag pair (for program API)
    kind = rng.randrange(4)
    chunks: List[str] = []
    if kind == 0:
        chunks.append(GLSL_VERTEX_450)
    elif kind == 1:
        chunks.append(GLSL_FRAGMENT_450)
    elif kind == 2:
        chunks.append(GLSL_COMPUTE_450)
    else:
        # For a pair, provide vertex as first chunk; the fuzzer may feed different stages separately
        chunks.append(GLSL_VERTEX_450)
        chunks.append(GLSL_FRAGMENT_450)
    # Optionally add a preamble or helper function as extra chunks
    if rng.random() < 0.7:
        chunks.append(rng.choice(GLSL_PREAMBLE_SNIPPETS))
    if rng.random() < 0.6:
        chunks.append(rng.choice(GLSL_FUNC_SNIPPETS))
    return chunks


def make_essl_pipeline(rng: random.Random) -> List[str]:
    # Provide ES vertex or fragment
    chunks: List[str] = []
    if rng.random() < 0.5:
        chunks.append(ESSL_VERTEX_310)
    else:
        chunks.append(ESSL_FRAGMENT_310)
    if rng.random() < 0.5:
        chunks.append(rng.choice(GLSL_PREAMBLE_SNIPPETS))
    return chunks


def make_hlsl_pipeline(rng: random.Random) -> List[str]:
    # Randomly vertex or pixel, or both
    chunks: List[str] = []
    if rng.random() < 0.5:
        chunks.append(HLSL_VS)
    if rng.random() < 0.5 or not chunks:
        chunks.append(HLSL_PS)
    return chunks


def assemble_chunks(chunks: List[str], rng: random.Random) -> bytes:
    # The fuzzer chooses 1..3 strings; we provide up to 3
    rng.shuffle(chunks)
    n = rng.randrange(1, min(3, len(chunks)) + 1)
    selected = chunks[:n]
    # Join with newlines to keep tokens separated if concatenated by the consumer
    text = "\n".join(selected)
    # Trim to size limit and ensure NUL termination for safe C-string usage
    b = text.encode('utf-8')
    if len(b) > 4096 - 1:
        b = b[:4096 - 1]
    return b + b"\0"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Pick a language family to vary parser behavior
    family = rng.randrange(3)  # 0=GLSL,1=ESSL,2=HLSL
    if family == 0:
        chunks = make_glsl_pipeline(rng)
    elif family == 1:
        chunks = make_essl_pipeline(rng)
    else:
        chunks = make_hlsl_pipeline(rng)
    return assemble_chunks(chunks, rng)

import random
import string
from typing import List

# Generator for identifier/name string buffers.
# This will create a bytes object containing a plausible C-like identifier
# possibly including namespace-like qualifiers and array/suffix patterns
# that are commonly seen in shader symbol names, while remaining valid for
# APIs that expect simple C identifiers.

_max_len = 128

_ident_start = string.ascii_letters + "_"
_ident_body = string.ascii_letters + string.digits + "_"

_builtin_like = [
    "gl_Position", "gl_FragCoord", "gl_FrontFacing", "gl_PointCoord",
    "gl_SampleID", "gl_SampleMask", "gl_VertexID", "gl_InstanceID",
    "gl_LocalInvocationID", "gl_GlobalInvocationID", "gl_WorkGroupSize",
]

_common_uniforms = [
    "u_MVP", "u_Model", "u_View", "u_Proj", "u_Time", "u_Frame",
    "u_Textures", "u_Diffuse", "u_Normal", "u_Specular", "u_Albedo",
]

_common_blocks = [
    "Globals", "FrameData", "Material", "Lighting", "Camera",
    "Transforms", "PostProcess", "Skinning",
]

_common_entry = ["main", "vs_main", "ps_main", "cs_main", "raygen", "closest_hit", "miss"]

_suffixes = ["", "_idx", "_loc", "_binding", "_set", "_arr", "_hdr", "_uv", "_pos", "_color"]


def _rand_ident(rng: random.Random, min_len: int = 1, max_len: int = 32) -> str:
    n = rng.randint(min_len, max_len)
    start = rng.choice(_ident_start)
    body = "".join(rng.choice(_ident_body) for _ in range(max(0, n - 1)))
    return start + body


def _qualify(rng: random.Random, base: str) -> str:
    # Occasionally produce struct-like or namespace-like qualification that remains identifier-safe
    # The fuzzer sites pass C strings; dots are typically allowed in GLSL for member access in source,
    # but API lookups often expect raw identifiers. So keep it simple: use underscores to qualify.
    parts = [base]
    if rng.random() < 0.3:
        parts.append(_rand_ident(rng, 3, 8))
    if rng.random() < 0.2:
        parts.append(_rand_ident(rng, 2, 6))
    name = "_".join(parts)
    # Optional numeric suffix often used in arrays
    if rng.random() < 0.35:
        name += f"_{rng.randint(0, 15)}"
    # Optional common suffix
    if rng.random() < 0.4:
        name += rng.choice(_suffixes)
    return name[:_max_len]


def _pick_base(rng: random.Random) -> str:
    # Choose from buckets to cover different API call sites
    bucket = rng.random()
    if bucket < 0.2:
        return rng.choice(_builtin_like)
    elif bucket < 0.45:
        return rng.choice(_common_uniforms)
    elif bucket < 0.65:
        return rng.choice(_common_blocks)
    elif bucket < 0.8:
        return rng.choice(_common_entry)
    else:
        # random user identifier with typical prefixes
        prefix = rng.choice(["u_", "g_", "s_", "cb_", "mat_", "light_", "attr_", "in_", "out_"])
        return prefix + _rand_ident(rng, 3, 16)


def _ensure_c_identifier(name: str) -> str:
    # APIs like OutputSpvHex varName require a C identifier. Sanitize strictly.
    if not name or name[0] not in _ident_start:
        name = "_" + (name or "v")
    sanitized = [name[0]]
    for c in name[1:]:
        sanitized.append(c if c in _ident_body else "_")
    out = "".join(sanitized)
    return out[:_max_len]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide a pattern to generate based on fuzz site variety
    mode = rng.random()

    if mode < 0.25:
        # Plain entry point or built-in-like
        base = _pick_base(rng)
        ident = _ensure_c_identifier(base)
    elif mode < 0.55:
        # Qualified uniform-like name
        base = _pick_base(rng)
        ident = _ensure_c_identifier(_qualify(rng, base))
    elif mode < 0.8:
        # Random identifier with common suffix/prefix
        prefix = rng.choice(["u_", "", "_", "block_", "attr_", "io_"])
        ident = _ensure_c_identifier(prefix + _rand_ident(rng, 4, 24) + rng.choice(_suffixes))
    else:
        # Array-style naming without brackets (safe for API names)
        base = _rand_ident(rng, 3, 12)
        ident = _ensure_c_identifier(f"{base}_{rng.randint(0, 63)}")

    # Encode as UTF-8 bytes, ensure non-empty and <= 4096
    if not ident:
        ident = "v"
    data = ident.encode("utf-8")
    if len(data) > 4096:
        data = data[:4096]
    return data
